import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BLUpqgOD.js";const m=JSON.parse('{"title":"Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/snapshots.md","filePath":"developers/commands/snapshots.md"}'),n={name:"developers/commands/snapshots.md"};function d(c,e,r,p,h,i){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; snapshot store knobs next Verse</span></span>
<span class="line"><span>s32&gt; snapshot store knobs next Chorus</span></span>
<span class="line"><span>s32&gt; snapshot list knobs</span></span>
<span class="line"><span>s32&gt; snapshot recall knobs 0</span></span>
<span class="line"><span>s32&gt; snapshot bank set knobs sync=1bar fade=1/4</span></span></code></pre></div><p><code>PART</code> is the bank: <code>knobs</code>, <code>lfos</code>, or <code>rack0</code>…<code>rack7</code>. <code>SLOT</code> is <code>0</code>–<code>31</code>. See <a href="/versions/cli/v1.3.47/snapshots/">Snapshots</a> for how banks work on the S32.</p><h2 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>snapshot list [PART]</code></td><td>Names, which slots are full, and the active one. Default <code>knobs</code></td></tr><tr><td><code>snapshot store PART [SLOT|next] [NAME]</code></td><td>Takes the current sound into a slot. A rack bank with no devices answers <code>BadRequest</code>; <code>Busy</code> during a fade</td></tr><tr><td><code>snapshot recall PART SLOT</code></td><td>Recalls a slot</td></tr><tr><td><code>snapshot delete PART SLOT</code></td><td>Asks first. Empties a slot. <code>Busy</code> during a fade</td></tr><tr><td><code>snapshot rename PART SLOT NAME</code></td><td>Renames without taking again</td></tr><tr><td><code>snapshot copy|swap|move PART SRC DEST</code></td><td><code>Busy</code> during a fade. An empty source answers <code>NotFound</code></td></tr></tbody></table><h2 id="bank-settings" tabindex="-1">Bank settings <a class="header-anchor" href="#bank-settings" aria-label="Permalink to &quot;Bank settings&quot;">​</a></h2><p><code>snapshot bank get PART</code> and <code>snapshot bank set PART sync=… fade=…</code> (each optional, at least one).</p><table tabindex="0"><thead><tr><th></th><th>Values</th></tr></thead><tbody><tr><td><code>sync=</code></td><td><code>immediate</code>, <code>1bar</code>, <code>2bars</code>, <code>3bars</code>, <code>4bars</code></td></tr><tr><td><code>fade=</code></td><td><code>off</code>, <code>1/16</code>, <code>1/8</code>, <code>1/4</code>, <code>1/2</code>, <code>1bar</code>, <code>2bars</code>, <code>4bars</code></td></tr></tbody></table><h2 id="in-snapshot" tabindex="-1">IN SNAPSHOT <a class="header-anchor" href="#in-snapshot" aria-label="Permalink to &quot;IN SNAPSHOT&quot;">​</a></h2><p>Each macro, each whole LFO and each whole device has an IN SNAPSHOT switch. So does each parameter. A rack or LFO recall, fade and morph moves a parameter only when both its switch and its owner&#39;s switch are <strong>YES</strong>. A knob recall writes through its macros: a macro that is on sets its parameter whatever the parameter&#39;s switches say. A take still stores everything. Recall doesn&#39;t change the switches.</p><table tabindex="0"><thead><tr><th>Command</th><th>Switch</th></tr></thead><tbody><tr><td><code>snapshot flags get device RACK DEV PARAM</code> / <code>set … in=yes|no morph=yes|no</code></td><td>One device parameter: IN SNAPSHOT and ALLOW MORPH, each optional; the other bit keeps its value</td></tr><tr><td><code>snapshot flags get lfo s32 INDEX PARAM</code> / <code>set … in=yes|no morph=yes|no</code></td><td>The same for one LFO parameter</td></tr><tr><td><code>snapshot parent get device RACK DEV</code> / <code>set … in=yes|no</code></td><td>A whole device</td></tr><tr><td><code>snapshot parent get lfo s32 INDEX</code> / <code>set … in=yes|no</code></td><td>A whole LFO</td></tr><tr><td><code>macro set POT MACRO in=yes|no</code></td><td>One macro</td></tr></tbody></table><h2 id="morph" tabindex="-1">Morph <a class="header-anchor" href="#morph" aria-label="Permalink to &quot;Morph&quot;">​</a></h2><p><code>snapshot morph get PART</code>, <code>snapshot morph set PART amount=N</code> and <code>snapshot morph clear PART</code> fade live toward the active slot. <code>amount=</code> runs <code>0</code>–<code>16383</code>. Above <code>0</code> it starts from what is playing now. <code>0</code> ends a running morph. <code>clear</code> drops it. While a recall fade is running the answer is <code>Busy</code>. See <a href="/versions/cli/v1.3.47/snapshots/morph">Morph</a>.</p><p>In a fresh <code>s32 --loopback repl</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot store knobs next Verse</span></span>
<span class="line"><span>s32&gt; snapshot morph set knobs amount=8192</span></span>
<span class="line"><span>morph set part=knobs amount=8192</span></span>
<span class="line"><span>s32&gt; snapshot morph get knobs</span></span>
<span class="line"><span>part=knobs pinA=- pinB=0 morphing=1 amount=8192</span></span>
<span class="line"><span>s32&gt; snapshot morph set knobs amount=0</span></span>
<span class="line"><span>morph set part=knobs amount=0</span></span>
<span class="line"><span>s32&gt; snapshot morph get knobs</span></span>
<span class="line"><span>part=knobs pinA=- pinB=- morphing=0 amount=0</span></span></code></pre></div><h2 id="arrange" tabindex="-1">Arrange <a class="header-anchor" href="#arrange" aria-label="Permalink to &quot;Arrange&quot;">​</a></h2><p><a href="/versions/cli/v1.3.47/snapshots/lanes">Arrange</a> plays slots as a song: up to 256 rows, one column per bank.</p><p><code>snapshot arrange get</code> prints <code>repeat</code>, <code>rate</code>, <code>length</code>, the playing row (<code>song-row</code>), the armed <strong>QUEUE</strong> (<code>drop-row</code>, <code>none</code> when off), then each column.</p><p><code>snapshot arrange set</code> changes only the keys you name:</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th></tr></thead><tbody><tr><td><code>repeat</code></td><td><code>loop</code> or <code>once</code></td></tr><tr><td><code>rate</code></td><td>Bars per row, <code>1</code>–<code>128</code></td></tr><tr><td><code>length</code></td><td>Rows, <code>1</code>–<code>256</code></td></tr><tr><td><code>knobs</code>, <code>lfos</code>, <code>rack0</code>…</td><td>Slots and <code>rest</code>, comma-separated. A short list fills the rest of the column with <code>rest</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot arrange set repeat=once rate=4 knobs=0,1,0,1 lfos=0,rest,3</span></span></code></pre></div><p>A new project starts with <strong>ARRANGE</strong> off. <code>snapshot arrange set</code> writes the song, not that switch: turn <strong>ARRANGE</strong> on in the pencil tab on the panel, or the playhead stays parked and <code>jump</code> / <code>queue</code> do nothing.</p><p><code>snapshot sequence get PART</code> and <code>snapshot sequence set PART rate=… [steps=…]</code> edit one column the same way.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>snapshot jump ROW</code></td><td>Moves the playhead to <code>ROW</code> (from <code>0</code>)</td></tr><tr><td><code>snapshot queue ROW</code></td><td>Arms a <strong>QUEUE</strong> on <code>ROW</code>. <code>snapshot queue off</code> disarms it</td></tr></tbody></table><h2 id="mapping" tabindex="-1">Mapping <a class="header-anchor" href="#mapping" aria-label="Permalink to &quot;Mapping&quot;">​</a></h2><p><code>macro set</code> and <code>extmap add</code> take <code>target=snapshot-slot</code> or <code>target=morph-amount</code> with <code>part=PART</code>. LFOs can&#39;t target either.</p><ul><li><strong>Snapshot slot:</strong> the note or Program Change you learn is pad <code>01</code> and the next 31 numbers fill the pads after it. Add <code>pad=1</code>–<code>pad=32</code> to map that one pad only, for example <code>extmap add ch=3 cc=34 target=snapshot-slot part=knobs pad=5</code>; it then ignores the bank&#39;s number and the CC sweep. <code>min=</code> and <code>max=</code> are slots <code>1</code>–<code>32</code>, as on the screen. The knob skips empty slots. A number outside 1–32 on assignment gives the full 1–32.</li><li><strong>Morph amount:</strong> always <code>0</code>–<code>16383</code>. <code>min=</code> and <code>max=</code> are ignored. <code>invert=</code> still works. It always picks up.</li></ul><p>Both turn IN SNAPSHOT to <strong>NO</strong> for that macro. To make it a normal macro again, set a new <code>mode=</code> (or <code>rack=</code>, <code>device=</code>, <code>param=</code>, <code>cvParam=</code>) without <code>target=</code>. IN SNAPSHOT comes back to <strong>YES</strong> and the range becomes the new mode&#39;s full range:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; macro set 0 0 target=morph-amount part=knobs</span></span>
<span class="line"><span>s32&gt; macro set 0 0 mode=cc msb=7</span></span>
<span class="line"><span>s32&gt; macro get 0 0</span></span></code></pre></div><h2 id="output-after-a-set" tabindex="-1">Output after a set <a class="header-anchor" href="#output-after-a-set" aria-label="Permalink to &quot;Output after a set&quot;">​</a></h2><p><code>snapshot sequence set</code>, <code>arrange set</code>, <code>flags set</code>, <code>parent set</code>, <code>bank set</code> and <code>morph set</code> print what they set, then the matching <code>get</code> (<a href="./session#a-set-prints-the-state-it-left">A set prints the state it left</a>). <code>flags set</code>, <code>parent set</code> and <code>bank set</code> already printed that state line, so the same line shows twice:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ s32 --loopback snapshot parent set rack 0 in=no</span></span>
<span class="line"><span>parent rack=0 in=no</span></span>
<span class="line"><span>parent rack=0 in=no</span></span>
<span class="line"><span>$ s32 --loopback snapshot bank set knobs sync=1bar</span></span>
<span class="line"><span>bank part=knobs sync=1bar fade=off</span></span>
<span class="line"><span>bank part=knobs sync=1bar fade=off</span></span></code></pre></div><p>With <code>--json</code>, lanes and Arrange columns are arrays with one number per step and <code>null</code> for a rest (<code>&quot;steps&quot;:[0,1,null]</code>); an Arrange <code>drop-row</code> of <code>none</code> is <code>null</code>, and <code>snapshot list --json</code> has <code>&quot;name&quot;:null</code> for an empty slot.</p>`,33)])])}const g=t(n,[["render",d]]);export{m as __pageData,g as default};
